<style>
#Page { width: stretch; height: stretch; }
#Cells { display: grid; width: stretch; grid-template-columns: repeat(auto-fill, minmax(calc(var(--size-xxl) * 4.4), 1fr)); gap: var(--space-lg); padding: var(--space-lg); }
.cell { display: flex; flex-direction: column; gap: var(--space-xs); min-width: 0; }
.cell.member-song-select, .cell.member-results, .cell.member-difficulty { grid-column: span 2; }
.caption { font: var(--text-caption); color: var(--ink-muted); }
.stage { display: flex; min-width: 0; min-height: calc(var(--size-xxl) * 1.6); align-items: flex-start; padding: var(--space-sm); border-radius: var(--radius-sm); background: var(--well); }
.cell.member-song-select .stage, .cell.member-results .stage { height: calc(var(--size-xxl) * 5); }
#Cells:size(compact) { grid-template-columns: minmax(0, 1fr); padding: var(--space-sm); gap: var(--space-md); }
.cell.member-song-select:size(compact), .cell.member-results:size(compact), .cell.member-difficulty:size(compact) { grid-column: span 1; }
.cell.member-song-select .stage:size(compact), .cell.member-results .stage:size(compact) { height: calc(var(--size-xxl) * 6.5); }
</style>
